// Decodes the golden frames generated by the Python bridge
// (protocol/vectors.txt) — proves both sides speak the same protocol.
#include <stdlib.h>

#include <fstream>
#include <map>
#include <sstream>
#include <string>
#include <vector>

#include "check.h"
#include "rigdash/protocol.h"

using namespace rigdash;

static std::map<std::string, Frame> loadVectors() {
  std::map<std::string, Frame> out;
  std::ifstream in(VECTORS_FILE);
  std::string line;
  while (std::getline(in, line)) {
    if (line.empty() || line[0] == '#') continue;
    std::istringstream ss(line);
    std::string name, hex;
    ss >> name >> hex;
    FrameParser p;
    int frames = 0;
    for (size_t i = 0; i + 1 < hex.size(); i += 2) {
      p.push(static_cast<uint8_t>(strtoul(hex.substr(i, 2).c_str(), nullptr, 16)));
      while (p.next()) {
        out[name] = p.frame();
        ++frames;
      }
    }
    if (frames != 1) printf("  vector %s produced %d frames\n", name.c_str(), frames);
  }
  return out;
}

TEST(vectors_all_decode) {
  auto v = loadVectors();
  CHECK_EQ(v.size(), 4u);
  CHECK_EQ(v["hello"].type, kMsgHello);
  CHECK_EQ(v["hello"].payload[0], kProtocolVersion);
}

TEST(vectors_telemetry_basic) {
  auto v = loadVectors();
  Telemetry t;
  CHECK_EQ(v["telemetry_basic"].type, kMsgTelemetry);
  CHECK(decodeTelemetry(v["telemetry_basic"].payload, v["telemetry_basic"].len, t));
  CHECK_EQ(t.current_lap_ms, 88200u);
  CHECK_EQ(t.last_lap_ms, 89012u);
  CHECK_EQ(t.best_lap_ms, 87950u);
  CHECK_EQ(t.last_pit_ms, 0u);
  CHECK_EQ(t.delta_ms, -345);
  CHECK_EQ(t.lap_number, 1);
  CHECK_EQ(t.position, 1);
  CHECK_EQ(t.gear, 3);
  CHECK_EQ(t.speed_kmh, 187);
  CHECK_EQ(t.fuel_laps_x10, 0);
  CHECK_EQ(t.track_pos, 4321);
  CHECK_EQ(t.air_temp_x10, 261);
  CHECK_EQ(t.track_temp_x10, 372);
  CHECK_EQ(t.flags, kFlagEngineOn | kFlagIgnitionOn);
  CHECK(t.session == Session::Practice);
}

TEST(vectors_telemetry_pit) {
  auto v = loadVectors();
  Telemetry t;
  CHECK(decodeTelemetry(v["telemetry_pit"].payload, v["telemetry_pit"].len, t));
  CHECK_EQ(t.current_lap_ms, 12345u);
  CHECK_EQ(t.lap_number, 5);
  CHECK_EQ(t.position, 12);
  CHECK_EQ(t.gear, 0);
  CHECK_EQ(t.fuel_laps_x10, kFuelUnknown);
  CHECK_EQ(t.last_pit_ms, 23400u);
  CHECK_EQ(t.air_temp_x10, -55);
  CHECK_EQ(t.track_temp_x10, -12);
  CHECK_EQ(t.flags, kFlagPitLimiter | kFlagInPit | kFlagLapInvalid);
  CHECK(t.session == Session::Race);
}

TEST(vectors_track_info) {
  auto v = loadVectors();
  const Frame& f = v["track_info"];
  CHECK_EQ(f.type, kMsgTrackInfo);
  CHECK(std::string(reinterpret_cast<const char*>(f.payload), f.len) ==
        "Autodromo Enzo e Dino Ferrari");
}
